```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<title>风中的稻田</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.7.0/p5.min.js"></script>
<style>
  body { margin:0; font-family: 'Poppins', sans-serif; background:#f0f8ff; }
  #sidebar { position:fixed; top:0; right:0; width:260px; height:100%; background:#fff; box-shadow:-2px 0 5px rgba(0,0,0,0.1); padding:20px; box-sizing:border-box; overflow-y:auto; }
  #canvas-container { margin-right:260px; }
  h2 { margin-top:0; font-size:1.4em; }
  .control-group { margin-bottom:15px; }
  .control-group label { display:block; margin-bottom:5px; }
  .control-group input[type=range] { width:100%; }
  .value-display { font-weight:bold; }
  button { padding:8px 12px; margin-right:5px; background:#007bff; color:#fff; border:none; cursor:pointer; }
  button:hover { background:#0056b3; }
  #seed-display { font-weight:bold; }
</style>
</head>
<body>
<div id="canvas-container"></div>
<div id="sidebar">
  <h2>风中的稻田</h2>
  <div class="control-group">
    <label>种子 <span id="seed-display">12345</span></label>
    <button id="prev-seed">←</button>
    <button id="next-seed">→</button>
    <button id="random-seed">随机</button>
    <input type="number" id="jump-seed" placeholder="跳转种子" style="width:80px;">
    <button id="go-seed">Go</button>
  </div>
  <hr>
  <div class="control-group">
    <label>风力 <span id="wind-value" class="value-display">5</span></label>
    <input type="range" id="wind-slider" min="0" max="10" step="0.1" value="5">
  </div>
  <div class="control-group">
    <label>稻穗密度 <span id="density-value" class="value-display">120</span></label>
    <input type="range" id="density-slider" min="20" max="300" step="1" value="120">
  </div>
  <hr>
  <div class="control-group">
    <button id="regenerate">重新生成</button>
    <button id="reset">重置</button>
    <button id="download">下载 PNG</button>
  </div>
</div>

<script>
/* ---------- 参数与全局变量 ---------- */
let seed = 12345;
let windStrength = 5;   // 0-10
let density = 120;     // 20-300
let stalks = [];
let canvas;

// ---------- UI 事件 ---------- //
function updateSeedDisplay() {
  document.getElementById('seed-display').textContent = seed;
}
function setSeed(newSeed) {
  seed = newSeed;
  updateSeedDisplay();
  regenerate();
}
document.getElementById('prev-seed').onclick = () => setSeed(seed - 1);
document.getElementById('next-seed').onclick = () => setSeed(seed + 1);
document.getElementById('random-seed').onclick = () => setSeed(Math.floor(Math.random()*1000000));
document.getElementById('go-seed').onclick = () => {
  const val = parseInt(document.getElementById('jump-seed').value);
  if (!isNaN(val)) setSeed(val);
};

document.getElementById('wind-slider').oninput = (e) => {
  windStrength = parseFloat(e.target.value);
  document.getElementById('wind-value').textContent = windStrength.toFixed(1);
};
document.getElementById('density-slider').oninput = (e) => {
  density = parseInt(e.target.value);
  document.getElementById('density-value').textContent = density;
};

document.getElementById('regenerate').onclick = regenerate;
document.getElementById('reset').onclick = () => {
  seed = 12345;
  windStrength = 5;
  density = 120;
  document.getElementById('wind-slider').value = windStrength;
  document.getElementById('density-slider').value = density;
  document.getElementById('wind-value').textContent = windStrength.toFixed(1);
  document.getElementById('density-value').textContent = density;
  updateSeedDisplay();
  regenerate();
};
document.getElementById('download').onclick = () => {
  if (canvas) canvas.saveCanvas('rice_field', 'png');
};

/* ---------- p5.js 代码 ---------- */
function setup() {
  canvas = createCanvas(1200, 800);
  canvas.parent('canvas-container');
  noLoop();
  regenerate();
}

function regenerate() {
  // 重新设置种子
  randomSeed(seed);
  noiseSeed(seed);
  // 生成稻穗
  generateStalks();
  redraw();
}

function generateStalks() {
  stalks = [];
  const cols = Math.ceil(sqrt(density));
  const spacingX = width / cols;
  const spacingY = height / cols;
  for (let i = 0; i < density; i++) {
    const x = random(width);
    const y = random(height);
    const length = random(80, 150);
    const sway = random(0.5, 1.5);
    stalks.push(new RiceStalk(x, y, length, sway));
  }
}

class RiceStalk {
  constructor(x, y, len, sway) {
    this.x = x;
    this.y = y;
    this.len = len;
    this.sway = sway;
  }
  draw(t) {
    const noiseScale = 0.005;
    const angle = windStrength * this.sway * noise(this.x * noiseScale, this.y * noiseScale, t);
    push();
    translate(this.x, this.y);
    rotate(angle);
    stroke(34, 139, 34);
    strokeWeight(2);
    line(0, 0, 0, -this.len);
    pop();
  }
}

function draw() {
  background(230, 240, 255); // 轻柔天空色
  const t = frameCount * 0.02;
  for (let s of stalks) {
    s.draw(t);
  }
}
</script>
</body>
</html>
```

> **使用说明**  
> 1. 将上述 HTML 代码保存为 `rice_field.html`。  
> 2. 在浏览器中打开即可看到“风中的稻田”生成艺术。  
> 3. 通过侧边栏的种子导航器可切换不同种子，体验不同风暴。  
> 4. 调整“风力”和“稻穗密度”滑块，即可实时观察算法的变化。  
> 5. “重新生成”按钮会根据当前种子和参数重新生成稻穗；“重置”恢复默认设置；“下载 PNG”可保存当前画面。  

这份完整的 HTML 文件已包含所有必要的 UI、参数、种子控制以及基于 p5.js 的生成算法，满足“风中的稻田”这一主题的创作需求。祝你玩得开心！

下面是按 Anthropic 官方品牌规范改造后的完整 CSS。核心结论先说：**标题用 Poppins（回退 Arial），正文用 Lora（回退 Georgia）**，按钮属于 UI 控件而非正文，标签文字同样用 Poppins。

## 一、字体分配

| 元素 | 字体 | 回退 | 说明 |
|---|---|---|---|
| `h1`（Q3 汇报） | **Poppins** | Arial, Helvetica, sans-serif | 40px ≫ 24pt(32px) 阈值，属标题层级 |
| `p`（收入同比增长…） | **Lora** | Georgia, serif | 正文语义，用人文衬线 |
| `button`（查看详情） | **Poppins** | Arial | 非正文，是控件标签，与标题同族更统一 |

规范里 "24pt 及以上标题用 Poppins、正文用 Lora" 是按语义+字号双重判断；`24pt = 32px`（96dpi 下按 4/3 换算），本页 `h1` 设为 `2.5rem = 40px`，稳稳落在 Poppins 区间。

