## 2️⃣ 开发核心组件

### 2.1 `src/App.tsx`

```tsx
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { DragDropContext, Droppable, Draggable, DropResult } from "react-beautiful-dnd";
import { Column, Task } from "./types";

const initialColumns: Record<string, Column> = {
  todo: { id: "todo", title: "待办", tasks: [{ id: "1", content: "写 README" }] },
  inprogress: { id: "inprogress", title: "进行中", tasks: [] },
  done: { id: "done", title: "完成", tasks: [] },
};

export default function App() {
  const [columns, setColumns] = useState<Record<string, Column>>(initialColumns);

  const onDragEnd = (result: DropResult) => {
    const { source, destination } = result;
    if (!destination) return;

    const sourceCol = columns[source.droppableId];
    const destCol = columns[destination.droppableId];
    const sourceTasks = Array.from(sourceCol.tasks);
    const destTasks = Array.from(destCol.tasks);

    const [movedTask] = sourceTasks.splice(source.index, 1);
    destTasks.splice(destination.index, 0, movedTask);

    setColumns({
      ...columns,
      [source.droppableId]: { ...sourceCol, tasks: sourceTasks },
      [destination.droppableId]: { ...destCol, tasks: destTasks },
    });
  };

  const moveTask = (taskId: string, from: string, to: string) => {
    const fromCol = columns[from];
    const toCol = columns[to];
    const fromTasks = Array.from(fromCol.tasks);
    const toTasks = Array.from(toCol.tasks);
    const idx = fromTasks.findIndex((t) => t.id === taskId);
    if (idx === -1) return;
    const [task] = fromTasks.splice(idx, 1);
    toTasks.push(task);
    setColumns({
      ...columns,
      [from]: { ...fromCol, tasks: fromTasks },
      [to]: { ...toCol, tasks: toTasks },
    });
  };

  return (
    <div className="min-h-screen bg-gray-100 p-4">
      <h1 className="text-2xl font-bold mb-4 text-center">待办看板</h1>
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="grid grid-cols-3 gap-4">
          {Object.values(columns).map((col) => (
            <Droppable key={col.id} droppableId={col.id}>
              {(provided) => (
                <Card
                  className="h-full"
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                >
                  <CardHeader>
                    <CardTitle>{col.title}</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-2">
                    {col.tasks.map((task, index) => (
                      <Draggable key={task.id} draggableId={task.id} index={index}>
                        {(provided) => (
                          <div
                            ref={provided.innerRef}
                            {...provided.draggableProps}
                            {...provided.dragHandleProps}
                            className="p-2 bg-white rounded shadow"
                          >
                            <div className="flex justify-between items-center">
                              <span>{task.content}</span>
                              <div className="space-x-1">
                                {col.id !== "todo" && (
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() =>
                                      moveTask(task.id, col.id, "todo")
                                    }
                                  >
                                    ←
                                  </Button>
                                )}
                                {col.id !== "done" && (
                                  <Button
                                    size="sm"
                                    variant="outline"
                                    onClick={() =>
                                      moveTask(task.id, col.id, "done")
                                    }
                                  >
                                    →
                                  </Button>
                                )}
                              </div>
                            </div>
                          </div>
                        )}
                      </Draggable>
                    ))}
                    {provided.placeholder}
                  </CardContent>
                </Card>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
}
```

