#### 1. `TodoBoard.tsx`

```tsx
import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';

interface TodoItem {
  id: string;
  content: string;
}

interface Column {
  id: string;
  title: string;
  items: TodoItem[];
}

const initialColumns: Record<string, Column> = {
  todo: {
    id: 'todo',
    title: '待办',
    items: [
      { id: 'item-1', content: '完成项目提案' },
      { id: 'item-2', content: '准备周会演示' },
    ],
  },
  inProgress: {
    id: 'inProgress',
    title: '进行中',
    items: [],
  },
  completed: {
    id: 'completed',
    title: '完成',
    items: [],
  },
};

const TodoBoard: React.FC = () => {
  const [columns, setColumns] = useState(initialColumns);

  const onDragEnd = (result: any) => {
    if (!result.destination) return;

    const { sourceColumnId, sourceIndex, destinationColumnId, destinationIndex } = result;

    if (sourceColumnId === destinationColumnId) {
      const newItems = Array.from(columns[sourceColumnId].items);
      const [movedItem] = newItems.splice(sourceIndex, 1);
      newItems.splice(destinationIndex, 0, movedItem);
      setColumns({
        ...columns,
        [sourceColumnId]: {
          ...columns[sourceColumnId],
          items: newItems,
        },
      });
    } else {
      const sourceItems = Array.from(columns[sourceColumnId].items);
      const destinationItems = Array.from(columns[destinationColumnId].items);
      const [movedItem] = sourceItems.splice(sourceIndex, 1);
      destinationItems.splice(destinationIndex, 0, movedItem);
      setColumns({
        ...columns,
        [sourceColumnId]: {
          ...columns[sourceColumnId],
          items: sourceItems,
        },
        [destinationColumnId]: {
          ...columns[destinationColumnId],
          items: destinationItems,
        },
      });
    }
  };

  const moveItem = (itemId: string, sourceColumnId: string, destinationColumnId: string) => {
    const sourceItems = Array.from(columns[sourceColumnId].items);
    const destinationItems = Array.from(columns[destinationColumnId].items);
    const [movedItem] = sourceItems.filter(item => item.id === itemId);
    sourceItems.splice(sourceItems.indexOf(movedItem), 1);
    destinationItems.push(movedItem);
    setColumns({
      ...columns,
      [sourceColumnId]: {
        ...columns[sourceColumnId],
        items: sourceItems,
      },
      [destinationColumnId]: {
        ...columns[destinationColumnId],
        items: destinationItems,
      },
    });
  };

  return (
    <div className="flex gap-4 p-4">
      {Object.entries(columns).map(([columnId, column]) => (
