                            {...provided.draggableProps}
                            {...provided.dragHandleProps}
                            className="mb-2 p-2 border rounded shadow-sm"
                          >
                            {item.content}
                          </div>
                        )}
                      </Draggable>
                    ))}
                    {provided.placeholder}
                  </div>
                )}
              </Droppable>
